static class ResourceManager {
    private final List<AutoCloseable> resources = new ArrayList<>();
    void register(AutoCloseable r) { resources.add(r); }
    void closeAll() throws Exception {
        for (int i = resources.size() - 1; i >= 0; i--) {
            resources.get(i).close();
        }
    }
}

static class FailingConstructorResource implements AutoCloseable {
    FailingConstructorResource() { throw new RuntimeException("Blad konstruktora"); }
    public void close() { System.out.println("To sie nigdy nie wykona"); }
}

