    }
} catch (RuntimeException e) {
    System.out.println("Zlapano: " + e.getMessage());
    // 'a' i 'b' zostaly poprawnie zamkniete, 'c' i 'd' nigdy sie nie otworzyly
}

static void printFullExceptionChain(Throwable t) {
    if (t == null) return;
    System.out.println("Wyjatek: " + t);
    if (t.getCause() != null) {
        System.out.println("  Przyczyna:");
        printFullExceptionChain(t.getCause());
    }
    for (Throwable s : t.getSuppressed()) {
        System.out.println("  Stlumiony:");
        printFullExceptionChain(s);
    }
}

