static class PooledResource<T> implements AutoCloseable {
    private final List<T> pool;
    private final T borrowed;
    PooledResource(List<T> pool) {
        this.pool = pool;
        this.borrowed = pool.remove(0);
    }
    T get() { return borrowed; }
    public void close() { pool.add(borrowed); }
}

