static class TransactionalFileWriter implements AutoCloseable {
    private final Path tempFile, targetFile;
    private final BufferedWriter writer;
    private boolean failed = false;

    TransactionalFileWriter(Path targetFile) throws IOException {
        this.targetFile = targetFile;
        this.tempFile = Path.of(targetFile + ".tmp");
        this.writer = Files.newBufferedWriter(tempFile);
    }

    void write(String line) throws IOException { writer.write(line); writer.newLine(); }
    void markFailed() { failed = true; }

    public void close() throws IOException {
        writer.close();
        if (failed) {
            Files.deleteIfExists(tempFile);
        } else {
            Files.move(tempFile, targetFile, StandardCopyOption.REPLACE_EXISTING);
        }
    }
}

static void runWithResources(List<AutoCloseable> resources, Runnable body) throws Exception {
    RuntimeException bodyException = null;
    try {
        body.run();
    } catch (RuntimeException e) {
        bodyException = e;
    }

    Exception firstCloseException = null;
    for (int i = resources.size() - 1; i >= 0; i--) {
        try {
            resources.get(i).close();
        } catch (Exception closeEx) {
            if (bodyException != null) {
                bodyException.addSuppressed(closeEx);
            } else if (firstCloseException == null) {
                firstCloseException = closeEx;
            }
        }
    }

    if (bodyException != null) throw bodyException;
    if (firstCloseException != null) throw firstCloseException;
}

static class LoggingReader implements AutoCloseable {
    private final BufferedReader reader;
    LoggingReader(Path p) throws IOException { reader = Files.newBufferedReader(p); }
    String readLine() throws IOException { return reader.readLine(); }
    public void close() throws IOException { reader.close(); System.out.println("Reader zamkniety"); }
}

static class LoggingWriterFailingClose implements AutoCloseable {
    private final BufferedWriter writer;
    LoggingWriterFailingClose(Path p) throws IOException { writer = Files.newBufferedWriter(p); }
    void write(String s) throws IOException { writer.write(s); writer.newLine(); }
    public void close() throws IOException {
        writer.close();
        throw new IOException("Symulowany blad przy zamykaniu writera");
    }
}

